# ============================================================================
# COLLECTION FREEZE -- do not edit this file during a collection campaign
# without explicit sign-off.
#
# This file is in the code-fingerprint closure of every collection target
# (tasks/config/code_fingerprint.py). Editing it changes the version of every
# demo recorded afterwards, and review_demos will refuse to put those demos in
# an existing dataset. The cost is a re-collection, not a fix. Comments and
# docstrings do not count (the fingerprint hashes the de-commented AST);
# code does.
# ============================================================================
"""Environment-layer simulation config — the single source of truth.

Every in-house task env returns ``make_sim_config(...)`` from its
``_default_sim_config`` instead of hand-writing a SimConfig. The point is to make
it impossible for the collection side and the training side to drift apart: a
demo recorded under one set of solver/contact settings is only valid if training
replays it under the same ones.

Locked decisions:

- solver 24/8, ONE tier for every task. Sub-task policies have to compose into
  long-horizon tasks, so collection, sub-task training and long-horizon training
  must all share the same dynamics. Per-task solver tiers would break that.
- contact_offset 1mm project-wide. The 20mm default smears out mm-scale features
  (cap knurling, threads); tunnelling was measured NOT to bind below ~1.5 m/s
  contact speed, which covers every task in the family. rest_offset 0 keeps
  bodies resting at true geometric contact.
- TGS / PCM / friction-every-iteration set explicitly rather than inherited, so
  an upstream default change cannot silently alter our physics.
- enhanced determinism ON: costs some solver parallelism, buys bit-level
  reproducibility across runs. It does not affect single-step physics.
- sleep_threshold 0 (never sleep). The 0.005 default puts anything slower than
  ~10 cm/s to sleep, which shows up as slow-moving objects freezing mid-motion —
  an artifact with no real-world counterpart.
- CCD OFF: the task family is quasi-static. A genuinely fast task would need it
  re-enabled here (this function deliberately does not expose it as a knob).
- gravity and the fallback contact material are pinned explicitly; see below.

sim_freq is 400 FLEET-WIDE (user decision). One number for every
task: sub-task policies must compose into long-horizon tasks, so the
transition dynamics may not differ across tasks (same argument as the single
solver tier). 400 over 200 was an engineering call: demos are collected once
inside a hard two-week window and must be recorded under the best contact
fidelity available, while training compute is elastic — measured cost is
~2.0x on physics-bound state RL (512-env GPU: 1863 -> 944 env-step/s) and
~1.2-1.5x on image-based pipelines; CPU teleop keeps an 8x realtime margin.
Per-task overrides of sim_freq are for experiments only — shipping a task on
a different rate breaks the uniformity this file exists to guarantee.
control_freq is fixed at 20 — it IS the demo and training action rate, so it
is not a tuning knob.

NOTE: jqy's articulated_open_close (box-open) is deliberately NOT wired to this
profile yet — changing another owner's task dynamics needs their sign-off first.

Wiring status on this branch: the cabinet_pour family is
profile-wired. Stragglers with PRIVATE configs, to be wired one by one as they
enter the collection plan (each needs its own re-validation under the new
dynamics, per the task-onboarding rule): keyboard_typing (400 Hz but 0.8 mm
contact offset, no determinism/gravity pins), grasping,
pick_single_ycb_to_goal_table, rotate_single_object_in_hand (hand-written
configs), and peg_insertion / scissor_actuation / rotate_valve, which sit on
BARE ManiSkill defaults (100 Hz, solver 15/1, 2 cm contact offset) —
upstream/robodex ownership, do not rewire without sign-off.
"""

from mani_skill.utils.structs.types import (
    DefaultMaterialsConfig,
    GPUMemoryConfig,
    SceneConfig,
    SimConfig,
)

SIM_FREQ_DEFAULT = 400
CONTROL_FREQ = 20
SOLVER_POSITION_ITERS = 24
SOLVER_VELOCITY_ITERS = 8
CONTACT_OFFSET = 0.001  # 1 mm, uniform across every task
GRAVITY = (0.0, 0.0, -9.81)  # real value, pinned explicitly (not inherited)

# Global FALLBACK contact material: every collision surface that was never given
# an explicit material lands on these three numbers.
#
# This is a fallback, NOT a design value — 0.3/0.3 is the ManiSkill default
# inherited from Unity convention and has no physical basis. Today it still
# catches non-Panda robot families and task objects not yet migrated to explicit
# profiles (for example YCB, laptop, keyboard and mouse). All project-table-builder
# table/ground shapes, Sharpa palm/phalanx structure, and every Panda/mount/base
# structure no longer depend on it. Once the remaining assets are migrated, nothing should
# depend on this. It is spelled out here so it is visible and auditable instead
# of being an invisible default.
DEFAULT_MATERIAL_STATIC_FRICTION = 0.3
DEFAULT_MATERIAL_DYNAMIC_FRICTION = 0.3
DEFAULT_MATERIAL_RESTITUTION = 0.0


def make_sim_config(
    sim_freq: int = SIM_FREQ_DEFAULT,
    *,
    spacing: float = 5.0,
    max_rigid_contact_count: int = 2**20,
    max_rigid_patch_count: int = 2**19,
    found_lost_pairs_capacity: int = 2**25,
) -> SimConfig:
    """The locked environment-layer config.

    Only ``sim_freq`` (task-overridable) and the GPU buffer sizes (pure capacity,
    not physics) are exposed. Solver iterations, contact offsets and the physics
    flags are deliberately NOT parameters: they are project-wide locked values.
    Changing one means editing this file, which changes every task at once and
    invalidates demos recorded under the old dynamics — they would need
    re-collection.
    """
    assert sim_freq % CONTROL_FREQ == 0, (
        f"sim_freq={sim_freq} must be an integer multiple of control_freq={CONTROL_FREQ}"
    )
    return SimConfig(
        spacing=spacing,
        sim_freq=sim_freq,
        control_freq=CONTROL_FREQ,
        scene_config=SceneConfig(
            gravity=list(GRAVITY),
            solver_position_iterations=SOLVER_POSITION_ITERS,
            solver_velocity_iterations=SOLVER_VELOCITY_ITERS,
            contact_offset=CONTACT_OFFSET,
            rest_offset=0.0,
            bounce_threshold=2.0,
            sleep_threshold=0.0,
            enable_pcm=True,
            enable_tgs=True,
            enable_ccd=False,
            enable_enhanced_determinism=True,
            enable_friction_every_iteration=True,
        ),
        default_materials_config=DefaultMaterialsConfig(
            static_friction=DEFAULT_MATERIAL_STATIC_FRICTION,
            dynamic_friction=DEFAULT_MATERIAL_DYNAMIC_FRICTION,
            restitution=DEFAULT_MATERIAL_RESTITUTION,
        ),
        gpu_memory_config=GPUMemoryConfig(
            max_rigid_contact_count=max_rigid_contact_count,
            max_rigid_patch_count=max_rigid_patch_count,
            found_lost_pairs_capacity=found_lost_pairs_capacity,
        ),
    )
